import sys,os,json,hashlib
from pathlib import Path
os.environ['CUBLAS_WORKSPACE_CONFIG']=':4096:8'
sys.path.insert(0,'/tealab-data/rjin02/RVCBench/checkpoints/fish-speech-s2-native')
import torch
from fish_speech.models.dac.inference import load_model
from fish_speech.inference_engine.reference_loader import ReferenceLoader
from fish_speech.inference_engine.vq_manager import VQManager
from fish_speech.utils import set_seed
set_seed(42);torch.set_num_threads(8)
det='--deterministic' in sys.argv
torch.use_deterministic_algorithms(det)
codec=load_model('modded_dac_vq','/tealab-data/rjin02/AudioWatermarkBench/checkpoints/s2-pro/codec.pth','cuda:0')
class Engine(ReferenceLoader,VQManager):
    def __init__(self):ReferenceLoader.__init__(self);self.decoder_model=codec
engine=Engine()
audio=Path('/tealab-data/rjin02/RVCBench/data/Libritts/audios/121/121_127105_000043_000007.wav').read_bytes()
def h(t):
    return hashlib.sha256(t.detach().contiguous().view(torch.uint8).cpu().numpy().tobytes()).hexdigest()
observations=[];current=[]
def hook(name):
    def observe(module,args,result):
        if isinstance(result,torch.Tensor):
            current.append({'module':name,'input':h(args[0]) if args and isinstance(args[0],torch.Tensor) else None,'output':h(result),'shape':list(result.shape),'dtype':str(result.dtype)})
    return observe
handles=[module.register_forward_hook(hook(name)) for name,module in codec.named_modules() if name]
rows=[]
with torch.inference_mode():
    before={name:h(t) for name,t in codec.named_parameters()}
    for i in range(3):
        current=[];codes=engine.encode_reference(audio,True)
        observations.append(current);rows.append({'iteration':i,'tokens_sha256':h(codes)})
    after={name:h(t) for name,t in codec.named_parameters()}
for handle in handles:handle.remove()
first,second=observations[:2];a={r['module']:r for r in first};b={r['module']:r for r in second}
changed=[{'module':r['module'],'first':r,'second':b[r['module']]} for r in first if r['module'] in b and r['output']!=b[r['module']]['output']]
x={'status':'complete','deterministic_algorithms':det,'source_file':__file__,'source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'audio_sha256':hashlib.sha256(audio).hexdigest(),'rows':rows,'first_changed_layers':changed[:15],'changed_layer_count':len(changed),'changed_parameters':[name for name in before if before[name]!=after[name]],'observations':observations}
Path('/tealab-data/rjin02/RVCBench/reproduction/comparisons/fish_s2_codec_layer_probe'+('_deterministic' if det else '')+'.json').write_text(json.dumps(x,indent=2)+'\n')
print(json.dumps({k:v for k,v in x.items() if k not in ['observations','first_changed_layers']},indent=2),flush=True)
print(json.dumps(changed[:3],indent=2),flush=True)
